                                      frame:CGRectMake(13 + buttonW + gap, 9, buttonW, 34)];
    restore.enabled = !workspace.isBuilding && workspace.hasAnyApplied;
    build.enabled = [ZNBinaryBuildCoordinator sharedCoordinator].canBuild;
