    }
    row.target = @"UnityFramework";
    row.explicitTarget = YES;
    row.offsetText = query;
    row.enabledText = @"";
    row.originalHex = @"";
    row.validated = NO;
    row.validator = nil;
    row.statusText = @"来自 Method Finder · 请填写 Patch 字节后执行读取验证";
