            if ([usedLabels containsObject:label]) continue;
            NSString *oldPrefix = spec[@"old"];
            NSString *newPrefix = spec[@"title"];
            if ([label.text hasPrefix:oldPrefix] || [label.text hasPrefix:newPrefix]) {
                target = label;
                break;
            }
        }
