static NSArray<NSString *> *ZNM43Assemblies(void) {
    ZNIL2CPPResolver *resolver = [ZNIL2CPPResolver sharedResolver];
    [resolver refresh];
    NSString *path = resolver.unityPath ?: @"";
    void *handle = NULL;
