    if (parts.count != expected) {
        if (error) *error = [NSString stringWithFormat:@"需要 %lu 个浮点分量，当前=%lu", (unsigned long)expected, (unsigned long)parts.count];
        return NO;
    }
    for (NSUInteger i = 0; i < expected; i++) {
        const char *raw = parts[i].UTF8String;
        if (!raw) return NO;
