static BOOL ZNM442AllHex(NSString *value, BOOL *hasDigit) {
    NSString *s = ZNM442Trim(value);
    if (!s.length) return NO;
    BOOL digit = NO;
    for (NSUInteger i = 0; i < s.length; i++) {
