                              (long)argc,
                              (unsigned long long)methodRVA,
                              suffix,
                              shared]];
    [[ZNRuntimeLogger sharedLogger] log:[NSString stringWithFormat:@"[m4.5-owning-method-ui] query=%@ rva=0x%llX candidates=%lu start=0x%llX delta=0x%llX",
