        : [NSString stringWithFormat:@"搜索结果（%lu/%lu）",(unsigned long)visible.count,(unsigned long)all.count];
    UILabel *title=[self label:countText size:11.8 weight:UIFontWeightSemibold color:self.theme.primaryTextColor];
