static NSUInteger ZNM55CompleteStaticRows(void) {
    NSUInteger count = 0;
    for (ZNBinaryPatchRow *row in [ZNBinaryPatchWorkspace sharedWorkspace].rows ?: @[]) {
        if (row.offsetText.length > 0 && row.enabledText.length > 0) count++;
